                    if (columnIndex < 0 || columnIndex >= row.Cells.Length)
                    {
                        isValid = false;
                        report.Add(new DataIssue
                        {
                            Record = row.Number,
                            Column = @"weaponId",
                            Message = "열에 대응하는 셀이 없습니다."
                        });
                    }
                    else
                    {
                        string raw = row.Cells[columnIndex];
                        if (string.IsNullOrWhiteSpace(raw))
                        {
                            isValid = false;
                            report.Add(new DataIssue
                            {
                                Record = row.Number,
                                Column = @"weaponId",
                                RawValue = raw,
                                Message = "필수 값이 비어 있습니다."
                            });
                        }
                        else
                        {
                            if (!CsvValueConverter.TryInt(raw, out int weaponIdValue))
                            {
                                isValid = false;
                                report.Add(new DataIssue
                                {
                                    Record = row.Number,
                                    Column = @"weaponId",
                                    RawValue = raw,
                                    Message = "값을 int 타입으로 변환할 수 없습니다."
                                });
                            }
                            else
                            {
                                candidate.weaponId = weaponIdValue;
                            }
                        }
                    }
                }
            }
            // weaponType 필드의 CSV 값을 읽고 변환한다.
            {
                bool hasColumn = header.TryGetValue(@"weaponType", out int columnIndex);
                if (!hasColumn)
                {
                    isValid = false;
                    report.Add(new DataIssue
                    {
                        Record = row.Number,
                        Column = @"weaponType",
                        Message = "필수 열이 없습니다."
                    });
                }
                else
                {
                    if (columnIndex < 0 || columnIndex >= row.Cells.Length)
                    {
                        isValid = false;
                        report.Add(new DataIssue
                        {
                            Record = row.Number,
                            Column = @"weaponType",
                            Message = "열에 대응하는 셀이 없습니다."
                        });
                    }
                    else
                    {
                        string raw = row.Cells[columnIndex];
                        if (string.IsNullOrWhiteSpace(raw))
                        {
                            isValid = false;
                            report.Add(new DataIssue
                            {
                                Record = row.Number,
                                Column = @"weaponType",
                                RawValue = raw,
                                Message = "필수 값이 비어 있습니다."
                            });
                        }
                        else
                        {
                            if (!CsvValueConverter.TryEnum<global::WeaponType>(raw, out global::WeaponType weaponTypeValue))
                            {
                                isValid = false;
                                report.Add(new DataIssue
                                {
                                    Record = row.Number,
                                    Column = @"weaponType",
                                    RawValue = raw,
                                    Message = "값을 WeaponType 타입으로 변환할 수 없습니다."
                                });
                            }
                            else
                            {
                                candidate.weaponType = weaponTypeValue;
                            }
                        }
                    }
                }
            }
            if (!isValid)
                return false;

            result = candidate;
            return true;
        }
    }
}
